//! Phase 06 integration tests: serialization, import/export, and clipboard
//! interchange.
//!
//! TS oracles: `packages/core/src/io/io.test.ts` (envelope shape,
//! round-trips, clear-on-import, skips, rejections, deleted exclusion) and
//! `packages/core/src/io/import-json.ts` (version migration, repair rules,
//! atomicity). TS-authored fixtures (`fixtures/basic.json`,
//! `fixtures/all-types.json` — generated by `exportSceneToJSON`, never
//! hand-written) prove wire compatibility in the TS → Rust direction.
//!
//! Covered (module 08 exit criteria): versioned schema, serialize,
//! deserialize, migration/repair, validation, atomic import (direct and
//! history-tracked), clipboard payload (versioned + TS bare-array),
//! fresh-ID paste via core, repeated paste, and export semantics
//! (transient-free envelope, hidden-aware PNG planning).

use nary_core::clipboard::{Clipboard, ClipboardAdapter};
use nary_core::document::Document;
use nary_core::element::CounterIdGenerator;
use nary_core::element::{
    create_arrow, create_ellipse, create_frame, create_freedraw, create_image, create_instance,
    create_line, create_path, create_rectangle, create_text, AutoLayoutConfig, Binding,
    ChildLayoutSizing, ConstraintAnchor, Constraints, CounterAxisAlign, CropRegion, Element,
    ElementFillStyle, ElementId, FillStyle, FramePadding, FrameSizing, GradientStop, GradientType,
    LayoutDirection, PatchValue, PathSegment, PrimaryAxisAlign, StrokeStyle, TextAlign,
};
use nary_core::history::HistoryManager;
use nary_io::{
    decode_clipboard, encode_clipboard, export_str, import_str, import_str_tracked,
    plan_png_export, publish_clipboard, subscribe_clipboard, PngExportOptions,
};

const BASIC_FIXTURE: &str = include_str!("fixtures/basic.json");
const ALL_TYPES_FIXTURE: &str = include_str!("fixtures/all-types.json");

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

fn empty_doc() -> Document {
    Document::new()
}

/// Builds a document exercising every built-in variant plus the style and
/// layout corners (radial gradient, cross-hatch, dashed, auto-layout,
/// crop, overrides, constraints).
fn full_coverage_doc(gen: &mut CounterIdGenerator) -> Document {
    let mut doc = Document::new();

    let mut rect = create_rectangle(gen);
    rect.base.id = ElementId::of("rect-1");
    rect.base.background_color = FillStyle::Solid {
        color: "#e8f4fc".to_string(),
    };
    rect.roundness = Some(8.0);
    rect.base.constraints = Some(Constraints {
        horizontal: ConstraintAnchor::Center,
        vertical: ConstraintAnchor::Stretch,
    });
    doc.upsert(Element::Rectangle(rect)).unwrap();

    let mut ellipse = create_ellipse(gen);
    ellipse.base.id = ElementId::of("ellipse-1");
    ellipse.base.background_color = FillStyle::Gradient {
        gradient_type: GradientType::Radial,
        angle: 90.0,
        stops: vec![
            GradientStop {
                offset: 0.0,
                color: "#ffffff".to_string(),
            },
            GradientStop {
                offset: 1.0,
                color: "#000000".to_string(),
            },
        ],
    };
    ellipse.base.stroke_style = StrokeStyle::Dashed;
    ellipse.base.fill_style = ElementFillStyle::CrossHatch;
    ellipse.base.child_layout_sizing = Some(ChildLayoutSizing::Fill);
    doc.upsert(Element::Ellipse(ellipse)).unwrap();

    let mut line = create_line(gen);
    line.base.id = ElementId::of("line-1");
    line.points = vec![[0.0, 0.0], [100.0, 50.0], [200.0, 100.0]];
    doc.upsert(Element::Line(line)).unwrap();

    let mut arrow = create_arrow(gen);
    arrow.base.id = ElementId::of("arrow-1");
    arrow.points = vec![[0.0, 0.0], [200.0, 0.0]];
    arrow.start_binding = Some(Binding {
        element_id: ElementId::of("rect-1"),
        focus: 0.25,
        gap: 5.0,
    });
    doc.upsert(Element::Arrow(arrow)).unwrap();

    let mut text = create_text(gen);
    text.base.id = ElementId::of("text-1");
    text.text = "  padded\n\nsecond  ".to_string();
    text.text_align = TextAlign::Center;
    text.container_id = Some(ElementId::of("rect-1"));
    doc.upsert(Element::Text(text)).unwrap();

    let mut freedraw = create_freedraw(gen);
    freedraw.base.id = ElementId::of("freedraw-1");
    freedraw.points = vec![[0.0, 0.0], [30.0, 20.0]];
    freedraw.pressures = vec![0.5, 0.7];
    doc.upsert(Element::Freedraw(freedraw)).unwrap();

    let mut frame = create_frame(gen);
    frame.base.id = ElementId::of("frame-1");
    frame.auto_layout = Some(AutoLayoutConfig {
        direction: LayoutDirection::Horizontal,
        gap: 8.0,
        padding: FramePadding {
            top: 4.0,
            right: 4.0,
            bottom: 4.0,
            left: 4.0,
        },
        primary_axis_align: PrimaryAxisAlign::SpaceBetween,
        counter_axis_align: CounterAxisAlign::Stretch,
        sizing: FrameSizing::Hug,
    });
    doc.upsert(Element::Frame(frame)).unwrap();

    let mut child = create_rectangle(gen);
    child.base.id = ElementId::of("child-1");
    child.base.frame_id = Some(ElementId::of("frame-1"));
    doc.upsert(Element::Rectangle(child)).unwrap();

    let mut image = create_image(gen);
    image.base.id = ElementId::of("image-1");
    image.asset_id = "asset-9".to_string();
    image.crop = Some(CropRegion {
        x: 10.0,
        y: 10.0,
        width: 50.0,
        height: 50.0,
    });
    doc.upsert(Element::Image(image)).unwrap();

    let mut path = create_path(gen);
    path.base.id = ElementId::of("path-1");
    path.segments = vec![
        PathSegment {
            point: [0.0, 0.0],
            handle_in: None,
            handle_out: Some([50.0, 0.0]),
        },
        PathSegment {
            point: [100.0, 0.0],
            handle_in: Some([-50.0, 0.0]),
            handle_out: None,
        },
    ];
    path.closed = true;
    doc.upsert(Element::Path(path)).unwrap();

    let mut instance = create_instance(gen, "comp-1", 5.0, 5.0);
    instance.base.id = ElementId::of("instance-1");
    instance
        .overrides
        .insert("0".to_string(), PatchValue::Text("#ff0000".to_string()));
    instance
        .overrides
        .insert("1".to_string(), PatchValue::Number(12.0));
    doc.upsert(Element::Instance(instance)).unwrap();

    // A soft-deleted element must never leak into exports.
    let mut tombstone = create_rectangle(gen);
    tombstone.base.id = ElementId::of("gone");
    doc.upsert(Element::Rectangle(tombstone)).unwrap();
    doc.soft_delete("gone").unwrap();

    doc
}

fn visible_vec(doc: &Document) -> Vec<Element> {
    doc.get_all().into_iter().cloned().collect()
}

// ---------------------------------------------------------------------------
// Envelope shape + export semantics
// ---------------------------------------------------------------------------

#[test]
fn export_envelope_matches_ts_serialized_scene() {
    let mut gen = CounterIdGenerator::new();
    let doc = full_coverage_doc(&mut gen);
    let json = export_str(&doc).unwrap();
    let value: serde_json::Value = serde_json::from_str(&json).unwrap();
    let envelope = value.as_object().unwrap();

    // Exactly the TS keys — transient editor state cannot leak by shape.
    let mut keys: Vec<&str> = envelope.keys().map(String::as_str).collect();
    keys.sort_unstable();
    assert_eq!(
        keys,
        vec!["elementOrder", "elements", "schemaVersion", "version"]
    );
    assert_eq!(envelope["schemaVersion"], 1);
    assert_eq!(envelope["version"], 1);
    assert_eq!(envelope["elements"].as_array().unwrap().len(), 11);
    // Full order names the tombstone (TS export parity).
    let order = envelope["elementOrder"].as_array().unwrap();
    assert_eq!(order.len(), 12);
    assert!(order.iter().any(|id| id == "gone"));
    // The tombstone itself is excluded from elements.
    assert!(envelope["elements"]
        .as_array()
        .unwrap()
        .iter()
        .all(|element| element["id"] != "gone"));
}

#[test]
fn export_is_deterministic_across_repeated_calls_and_trips() {
    let mut gen = CounterIdGenerator::new();
    let doc = full_coverage_doc(&mut gen);
    let first = export_str(&doc).unwrap();
    let second = export_str(&doc).unwrap();
    assert_eq!(first, second);

    // A round trip sheds the tombstone's order entry (TS parity:
    // `importSceneFromJSON` restores the filtered order, so the dead id
    // drops out); from there the encoding is a fixed point.
    let mut restored = empty_doc();
    import_str(&mut restored, &first).unwrap();
    let re_export = export_str(&restored).unwrap();
    let mut third = empty_doc();
    import_str(&mut third, &re_export).unwrap();
    assert_eq!(export_str(&third).unwrap(), re_export);
    assert_eq!(visible_vec(&third), visible_vec(&doc));
}

// ---------------------------------------------------------------------------
// TS → Rust compatibility (committed TS-authored fixtures)
// ---------------------------------------------------------------------------

#[test]
fn ts_basic_fixture_imports_with_properties_intact() {
    let mut doc = empty_doc();
    let summary = import_str(&mut doc, BASIC_FIXTURE).unwrap();
    assert_eq!(summary.imported, 4);
    assert_eq!(summary.skipped, 0);

    let mut ids: Vec<&str> = doc
        .get_all()
        .iter()
        .map(|element| element.id().as_str())
        .collect();
    ids.sort_unstable();
    assert_eq!(ids, vec!["ellipse-1", "line-1", "rect-1", "text-1"]);

    let rect = doc.get("rect-1").unwrap();
    assert_eq!((rect.base().x, rect.base().y), (100.0, 200.0));
    assert!(matches!(
        rect.base().background_color,
        FillStyle::Solid { .. }
    ));
    if let Element::Ellipse(ellipse) = doc.get("ellipse-1").unwrap() {
        assert_eq!(ellipse.base.stroke_color, "#ff0000");
    } else {
        panic!("expected ellipse");
    }
    if let Element::Line(line) = doc.get("line-1").unwrap() {
        assert_eq!(line.points, vec![[0.0, 0.0], [100.0, 50.0], [200.0, 100.0]]);
    } else {
        panic!("expected line");
    }
    if let Element::Text(text) = doc.get("text-1").unwrap() {
        assert_eq!(text.text, "Hello World");
        assert_eq!(text.font_family, "Arial");
    } else {
        panic!("expected text");
    }
    doc.validate().unwrap();
}

#[test]
fn ts_all_types_fixture_round_trips_with_references_intact() {
    let mut doc = empty_doc();
    let summary = import_str(&mut doc, ALL_TYPES_FIXTURE).unwrap();
    assert_eq!(summary.imported, 13);
    assert_eq!(summary.skipped, 0);
    assert_eq!(doc.element_count(), 13);

    // References survive because their targets travel in the envelope.
    if let Element::Arrow(arrow) = doc.get("arrow-1").unwrap() {
        assert_eq!(
            arrow.start_binding.as_ref().unwrap().element_id.as_str(),
            "rect-1"
        );
        assert_eq!(
            arrow.end_binding.as_ref().unwrap().element_id.as_str(),
            "ellipse-1"
        );
    } else {
        panic!("expected arrow");
    }
    if let Element::Text(text) = doc.get("text-1").unwrap() {
        assert_eq!(text.container_id.as_ref().unwrap().as_str(), "rect-1");
        // Whitespace significant through the whole pipeline (ADR-0008).
        assert_eq!(text.text, "  padded\n\nsecond  ");
    } else {
        panic!("expected text");
    }
    assert_eq!(
        doc.get("rect-in-frame")
            .unwrap()
            .base()
            .frame_id
            .as_ref()
            .unwrap()
            .as_str(),
        "frame-1"
    );
    assert_eq!(
        doc.get("rect-1").unwrap().base().group_ids,
        vec![ElementId::of("group-a")]
    );
    assert!(doc.get("hidden-1").unwrap().base().hidden);
    assert!(doc.get("locked-1").unwrap().base().locked);
    assert_eq!(
        doc.get_all()
            .iter()
            .map(|element| element.id().as_str())
            .collect::<Vec<_>>(),
        vec![
            "rect-1",
            "ellipse-1",
            "line-1",
            "arrow-1",
            "text-1",
            "freedraw-1",
            "frame-1",
            "rect-in-frame",
            "image-1",
            "path-1",
            "instance-1",
            "hidden-1",
            "locked-1"
        ]
    );
    doc.validate().unwrap();

    // Export → re-import preserves the whole scene bit-for-bit.
    let json = export_str(&doc).unwrap();
    let mut second = empty_doc();
    import_str(&mut second, &json).unwrap();
    assert_eq!(visible_vec(&second), visible_vec(&doc));
    assert_eq!(second.order(), doc.order());
}

#[test]
fn rust_full_coverage_round_trip_is_exact() {
    let mut gen = CounterIdGenerator::new();
    let doc = full_coverage_doc(&mut gen);
    let json = export_str(&doc).unwrap();

    let mut restored = empty_doc();
    let summary = import_str(&mut restored, &json).unwrap();
    assert_eq!(summary.imported, 11);
    assert_eq!(summary.skipped, 0);
    assert_eq!(visible_vec(&restored), visible_vec(&doc));
    // The tombstone's order entry sheds on import (TS parity — the
    // restored order filters to admitted ids); visible order is intact.
    let expected_order: Vec<ElementId> = doc
        .order()
        .into_iter()
        .filter(|id| id.as_str() != "gone")
        .collect();
    assert_eq!(restored.order(), expected_order);
    restored.validate().unwrap();

    // Style and layout corners survive the trip.
    if let Element::Ellipse(ellipse) = restored.get("ellipse-1").unwrap() {
        assert!(matches!(
            ellipse.base.background_color,
            FillStyle::Gradient { .. }
        ));
        assert_eq!(ellipse.base.stroke_style, StrokeStyle::Dashed);
        assert_eq!(ellipse.base.fill_style, ElementFillStyle::CrossHatch);
    } else {
        panic!("expected ellipse");
    }
    if let Element::Frame(frame) = restored.get("frame-1").unwrap() {
        let layout = frame.auto_layout.as_ref().expect("auto-layout survives");
        assert_eq!(layout.primary_axis_align, PrimaryAxisAlign::SpaceBetween);
    } else {
        panic!("expected frame");
    }
    if let Element::Instance(instance) = restored.get("instance-1").unwrap() {
        assert_eq!(
            instance.overrides.get("0"),
            Some(&PatchValue::Text("#ff0000".to_string()))
        );
    } else {
        panic!("expected instance");
    }
}

// ---------------------------------------------------------------------------
// Version migration + validation
// ---------------------------------------------------------------------------

#[test]
fn missing_version_defaults_to_v1_and_empty_clears() {
    let mut gen = CounterIdGenerator::new();
    let mut doc = full_coverage_doc(&mut gen);

    let summary = import_str(&mut doc, r#"{"elements":[]}"#).unwrap();
    assert_eq!(summary.imported, 0);
    assert_eq!(summary.skipped, 0);
    assert_eq!(doc.element_count(), 0);

    // Legacy `version` alias without `schemaVersion` also loads.
    let mut doc = empty_doc();
    import_str(
        &mut doc,
        BASIC_FIXTURE.replace("\"schemaVersion\":1,", "").as_str(),
    )
    .unwrap();
    assert_eq!(doc.element_count(), 4);
}

#[test]
fn unsupported_versions_are_rejected() {
    for payload in [
        r#"{"schemaVersion":99,"version":99,"elements":[]}"#,
        r#"{"schemaVersion":2,"elements":[]}"#,
        r#"{"version":99,"elements":[]}"#,
    ] {
        let mut doc = empty_doc();
        let err = import_str(&mut doc, payload).unwrap_err();
        assert!(
            err.to_string().contains("unsupported scene version"),
            "{payload}: {err}"
        );
        assert_eq!(doc.element_count(), 0);
    }
}

#[test]
fn malformed_envelopes_are_rejected() {
    for payload in [
        "not json",
        "[1,2,3]",
        "\"just a string\"",
        "42",
        "{}",
        r#"{"schemaVersion":1,"elements":"bad"}"#,
        r#"{"schemaVersion":1}"#,
    ] {
        let mut doc = empty_doc();
        assert!(import_str(&mut doc, payload).is_err(), "{payload}");
        assert_eq!(doc.element_count(), 0);
    }
}

#[test]
fn zero_valid_elements_is_rejected() {
    let mut doc = empty_doc();
    let err = import_str(&mut doc, r#"{"version":1,"elements":[{"bad":true}]}"#).unwrap_err();
    assert!(err.to_string().contains("no valid elements"), "{err}");
}

const VALID_RECT: &str = r##"{"id":"ok","type":"rectangle","x":0,"y":0,"width":10,"height":10,"rotation":0,"strokeColor":"#000","backgroundColor":{"type":"solid","color":"#fff"},"strokeWidth":1,"strokeStyle":"solid","fillStyle":"solid","opacity":100,"seed":1,"version":0,"versionNonce":1,"isDeleted":false,"groupIds":[],"locked":false}"##;

#[test]
fn invalid_elements_skip_individually_with_counts() {
    let valid: serde_json::Value = serde_json::from_str(VALID_RECT).unwrap();
    let payload = serde_json::json!({
        "schemaVersion": 1,
        "elements": [
            valid,
            {"id": "unknown", "type": "nope"},
            {"id": "short"},
            {"id":"wavy","type":"rectangle","x":0,"y":0,"width":10,"height":10,"rotation":0,"strokeColor":"#000","backgroundColor":{"type":"solid","color":"#fff"},"strokeWidth":1,"strokeStyle":"wavy","fillStyle":"solid","opacity":100,"seed":1,"version":0,"versionNonce":1,"isDeleted":false,"groupIds":[],"locked":false},
            {"id":"fd","type":"freedraw","x":0,"y":0,"width":10,"height":10,"rotation":0,"strokeColor":"#000","backgroundColor":{"type":"solid","color":"#fff"},"strokeWidth":1,"strokeStyle":"solid","fillStyle":"solid","opacity":100,"seed":1,"version":0,"versionNonce":1,"isDeleted":false,"groupIds":[],"locked":false,"points":[[0,0],[1,1]],"pressures":[0.5]}
        ]
    })
    .to_string();
    let mut doc = empty_doc();
    let summary = import_str(&mut doc, &payload).unwrap();
    // Unknown tag, truncated object, unrepresentable style string, and
    // pressure/point length mismatch (domain validation) all skip.
    assert_eq!(summary.imported, 1);
    assert_eq!(summary.skipped, 4);
    assert!(doc.get("ok").is_some());
    assert_eq!(doc.element_count(), 1);
}

// ---------------------------------------------------------------------------
// Atomicity
// ---------------------------------------------------------------------------

#[test]
fn failed_imports_leave_the_document_untouched() {
    let bad_payloads = [
        "not json",
        r#"{"schemaVersion":99,"elements":[]}"#,
        r#"{"version":1,"elements":[{"bad":true}]}"#,
        r#"{"schemaVersion":1,"elements":"bad"}"#,
    ];
    for payload in bad_payloads {
        let mut gen = CounterIdGenerator::new();
        let mut doc = full_coverage_doc(&mut gen);
        let before = visible_vec(&doc);
        let order_before = doc.order();
        let nonce_before = doc.scene_nonce();

        assert!(import_str(&mut doc, payload).is_err(), "{payload}");
        assert_eq!(visible_vec(&doc), before, "{payload}");
        assert_eq!(doc.order(), order_before, "{payload}");
        assert_eq!(doc.scene_nonce(), nonce_before, "{payload}");
    }
}

#[test]
fn dangling_references_repair_to_none_and_validate() {
    let valid: serde_json::Value = serde_json::from_str(VALID_RECT).unwrap();
    let payload = serde_json::json!({
        "schemaVersion": 1,
        "elements": [
            valid,
            {"id":"arrow-x","type":"arrow","x":0,"y":0,"width":10,"height":0,"rotation":0,"strokeColor":"#000","backgroundColor":{"type":"solid","color":"transparent"},"strokeWidth":1,"strokeStyle":"solid","fillStyle":"solid","opacity":100,"seed":1,"version":0,"versionNonce":1,"isDeleted":false,"groupIds":["group-keep"],"locked":false,"frameId":"ghost-frame","points":[[0,0],[10,0]],"startBinding":{"elementId":"ghost","focus":0,"gap":1},"endBinding":{"elementId":"ok","focus":0,"gap":1},"startArrowhead":null,"endArrowhead":"arrow"},
            {"id":"text-x","type":"text","x":0,"y":0,"width":10,"height":10,"rotation":0,"strokeColor":"#000","backgroundColor":{"type":"solid","color":"transparent"},"strokeWidth":1,"strokeStyle":"solid","fillStyle":"solid","opacity":100,"seed":1,"version":0,"versionNonce":1,"isDeleted":false,"groupIds":[],"locked":false,"text":"hi","fontSize":16,"fontFamily":"Virgil","textAlign":"left","containerId":"ghost"}
        ]
    })
    .to_string();
    let mut doc = empty_doc();
    let summary = import_str(&mut doc, &payload).unwrap();
    assert_eq!(summary.imported, 3);

    if let Element::Arrow(arrow) = doc.get("arrow-x").unwrap() {
        assert_eq!(arrow.start_binding, None);
        assert_eq!(
            arrow.end_binding.as_ref().unwrap().element_id.as_str(),
            "ok"
        );
    } else {
        panic!("expected arrow");
    }
    assert_eq!(doc.get("arrow-x").unwrap().base().frame_id, None);
    // Group ids are opaque (not element references): kept verbatim.
    assert_eq!(
        doc.get("arrow-x").unwrap().base().group_ids,
        vec![ElementId::of("group-keep")]
    );
    if let Element::Text(text) = doc.get("text-x").unwrap() {
        assert_eq!(text.container_id, None);
    } else {
        panic!("expected text");
    }
    doc.validate().unwrap();
}

#[test]
fn order_restores_exactly_with_forward_compat_append() {
    // Reversed order restores reversed.
    let mut value: serde_json::Value = serde_json::from_str(BASIC_FIXTURE).unwrap();
    let mut order = value["elementOrder"].as_array().unwrap().clone();
    order.reverse();
    value["elementOrder"] = serde_json::Value::Array(order);
    let mut doc = empty_doc();
    import_str(&mut doc, &serde_json::to_string(&value).unwrap()).unwrap();
    assert_eq!(
        doc.get_all()
            .iter()
            .map(|element| element.id().as_str())
            .collect::<Vec<_>>(),
        vec!["text-1", "line-1", "ellipse-1", "rect-1"]
    );

    // An order missing a valid id appends it (forward-compat, TS parity).
    let mut value: serde_json::Value = serde_json::from_str(BASIC_FIXTURE).unwrap();
    let order: Vec<serde_json::Value> = value["elementOrder"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|id| *id != "line-1")
        .cloned()
        .collect();
    value["elementOrder"] = serde_json::Value::Array(order);
    let mut doc = empty_doc();
    import_str(&mut doc, &serde_json::to_string(&value).unwrap()).unwrap();
    assert_eq!(
        doc.get_all()
            .iter()
            .map(|element| element.id().as_str())
            .collect::<Vec<_>>(),
        vec!["rect-1", "ellipse-1", "text-1", "line-1"]
    );
}

// ---------------------------------------------------------------------------
// History-tracked import
// ---------------------------------------------------------------------------

#[test]
fn tracked_import_is_one_undo_entry_and_undo_restores() {
    let mut gen = CounterIdGenerator::new();
    let mut keeper = create_rectangle(&mut gen);
    keeper.base.id = ElementId::of("keeper");
    let mut doc = empty_doc();
    doc.upsert(Element::Rectangle(keeper)).unwrap();
    let mut history = HistoryManager::new();

    let summary = import_str_tracked(&mut doc, &mut history, BASIC_FIXTURE).unwrap();
    assert_eq!(summary.imported, 4);
    assert_eq!(doc.element_count(), 4);
    assert!(doc.get("keeper").unwrap().base().is_deleted);
    assert_eq!(history.undo_len(), 1);

    assert!(history.undo(&mut doc).unwrap());
    assert_eq!(doc.element_count(), 1);
    assert!(!doc.get("keeper").unwrap().base().is_deleted);
    assert!(doc.get("rect-1").is_none());

    assert!(history.redo(&mut doc).unwrap());
    assert_eq!(doc.element_count(), 4);
    assert!(doc.get("rect-1").is_some());
}

#[test]
fn failed_tracked_import_records_nothing_and_changes_nothing() {
    let mut gen = CounterIdGenerator::new();
    let mut keeper = create_rectangle(&mut gen);
    keeper.base.id = ElementId::of("keeper");
    let mut doc = empty_doc();
    doc.upsert(Element::Rectangle(keeper)).unwrap();
    let mut history = HistoryManager::new();
    let nonce_before = doc.scene_nonce();

    assert!(import_str_tracked(
        &mut doc,
        &mut history,
        r#"{"schemaVersion":99,"elements":[]}"#
    )
    .is_err());
    assert_eq!(history.undo_len(), 0);
    assert_eq!(doc.element_count(), 1);
    assert_eq!(doc.scene_nonce(), nonce_before);
}

// ---------------------------------------------------------------------------
// Clipboard codec + host boundary
// ---------------------------------------------------------------------------

struct MemClipboard {
    text: Option<String>,
}

impl ClipboardAdapter for MemClipboard {
    fn write_text(&mut self, text: String) {
        self.text = Some(text);
    }

    fn read_text(&self) -> Option<String> {
        self.text.clone()
    }
}

#[test]
fn clipboard_codec_round_trips_through_a_host_adapter() {
    let mut gen = CounterIdGenerator::new();
    let doc = full_coverage_doc(&mut gen);

    let mut clipboard = Clipboard::new();
    let copied = clipboard.copy(
        &doc,
        &[
            ElementId::of("rect-1"),
            ElementId::of("arrow-1"),
            ElementId::of("text-1"),
        ],
    );
    let mut host = MemClipboard { text: None };
    publish_clipboard(&mut host, &copied).unwrap();
    // Publish encodes exactly what the codec produces.
    assert_eq!(
        host.text.as_ref().unwrap(),
        &encode_clipboard(&copied).unwrap()
    );

    // The published payload is the versioned envelope.
    let published: serde_json::Value = serde_json::from_str(host.text.as_ref().unwrap()).unwrap();
    assert_eq!(published["schemaVersion"], 1);
    assert_eq!(published["elements"].as_array().unwrap().len(), 3);

    let decoded = subscribe_clipboard(&host)
        .unwrap()
        .expect("payload present");
    assert_eq!(decoded.skipped, 0);
    assert_eq!(decoded.elements.len(), 3);
    assert_eq!(decoded.elements[0].id().as_str(), "rect-1");
}

#[test]
fn clipboard_codec_reads_ts_bare_array_bytes() {
    // Exactly what TS `copyElements` writes to `navigator.clipboard`.
    let fixture: serde_json::Value = serde_json::from_str(BASIC_FIXTURE).unwrap();
    let bare = serde_json::to_string(&fixture["elements"]).unwrap();

    let decoded = decode_clipboard(&bare).unwrap();
    assert_eq!(decoded.elements.len(), 4);
    assert_eq!(decoded.skipped, 0);
    assert_eq!(decoded.elements[0].id().as_str(), "rect-1");
}

#[test]
fn clipboard_codec_rejects_bad_payloads() {
    assert!(decode_clipboard("not json").is_err());
    assert!(decode_clipboard("42").is_err());
    assert!(decode_clipboard(r#"{"schemaVersion":99,"elements":[]}"#).is_err());
    assert!(decode_clipboard(r#"{"schemaVersion":1,"elements":[{"bad":true}]}"#).is_err());
    assert!(decode_clipboard("[]").unwrap().elements.is_empty());

    let host = MemClipboard { text: None };
    assert!(subscribe_clipboard(&host).unwrap().is_none());
}

// ---------------------------------------------------------------------------
// PNG export planning
// ---------------------------------------------------------------------------

#[test]
fn png_plan_covers_visible_bounds_with_padding_and_scale() {
    let mut gen = CounterIdGenerator::new();
    let mut doc = empty_doc();
    let mut rect = create_rectangle(&mut gen);
    rect.base.id = ElementId::of("r1");
    rect.base.x = 10.0;
    rect.base.y = 10.0;
    rect.base.width = 100.0;
    rect.base.height = 80.0;
    doc.upsert(Element::Rectangle(rect)).unwrap();
    // A far-away hidden element must not move the content bounds.
    let mut hidden = create_rectangle(&mut gen);
    hidden.base.id = ElementId::of("h1");
    hidden.base.x = 1000.0;
    hidden.base.y = 1000.0;
    hidden.base.hidden = true;
    doc.upsert(Element::Rectangle(hidden)).unwrap();

    let plan = plan_png_export(&doc, &PngExportOptions::default()).unwrap();
    assert_eq!(
        plan.content_bounds,
        nary_core::geometry::Bounds::new(10.0, 10.0, 110.0, 90.0)
    );
    // (100 + 2×20) × 2 = 280; (80 + 2×20) × 2 = 240.
    assert_eq!(plan.canvas_width_px, 280);
    assert_eq!(plan.canvas_height_px, 240);
    assert_eq!(plan.effective_scale, 2.0);
    assert_eq!(plan.background, "transparent");
}

#[test]
fn png_plan_rejects_empty_scenes_and_clamps_huge_ones() {
    let doc = empty_doc();
    assert!(plan_png_export(&doc, &PngExportOptions::default()).is_err());

    let mut gen = CounterIdGenerator::new();
    let mut doc = empty_doc();
    let mut big = create_rectangle(&mut gen);
    big.base.id = ElementId::of("big");
    big.base.width = 10_000.0;
    big.base.height = 10_000.0;
    doc.upsert(Element::Rectangle(big)).unwrap();

    let plan = plan_png_export(&doc, &PngExportOptions::default()).unwrap();
    assert_eq!(plan.canvas_width_px, 4096);
    assert_eq!(plan.canvas_height_px, 4096);
    assert!(plan.effective_scale < 2.0);
}

// ---------------------------------------------------------------------------
// Paste-via-clipboard over imported content (cross-feature integration)
// ---------------------------------------------------------------------------

#[test]
fn copy_paste_paste_over_ts_import_mints_fresh_ids() {
    // Module 12 scenario: copy → paste → paste → verify fresh IDs.
    let mut doc = empty_doc();
    import_str(&mut doc, BASIC_FIXTURE).unwrap();
    let mut history = HistoryManager::new();

    let mut clipboard = Clipboard::new();
    clipboard.copy(&doc, &[ElementId::of("rect-1")]);
    let first = clipboard.paste(&mut doc, &mut history, None).unwrap();
    let second = clipboard.paste(&mut doc, &mut history, None).unwrap();
    assert_ne!(first[0].id().as_str(), "rect-1");
    assert_ne!(second[0].id().as_str(), "rect-1");
    assert_ne!(first[0].id(), second[0].id());
    assert_eq!(doc.element_count(), 6);
    doc.validate().unwrap();
}

#[test]
fn custom_typed_elements_skip_with_count_while_builtins_import() {
    // Pinned intentional behavior (gap-analysis E1): `Custom` round-trips
    // out through export but never back in — the io layer has no access to
    // the instance-scoped shape registry (dependency direction), so hosts
    // re-register types at runtime and unknown scene types skip loudly
    // instead of failing the import.
    let mut doc = empty_doc();
    let scene = serde_json::json!({
        "schemaVersion": 1,
        "elements": [
            {
                "id": "rect-9", "type": "rectangle",
                "x": 0, "y": 0, "width": 10, "height": 10, "rotation": 0,
                "strokeColor": "#000000",
                "backgroundColor": {"type": "solid", "color": "#ffffff"},
                "strokeWidth": 1, "strokeStyle": "solid", "fillStyle": "solid",
                "opacity": 100, "seed": 1, "version": 0, "versionNonce": 1,
                "isDeleted": false, "groupIds": [], "locked": false
            },
            {"id": "sticker-1", "type": "acme.sticker", "data": {"faces": 5}},
        ],
        "elementOrder": ["rect-9", "sticker-1"],
    });
    let summary = import_str(&mut doc, &scene.to_string()).unwrap();
    assert_eq!(summary.imported, 1);
    assert_eq!(summary.skipped, 1);
    assert!(doc.get("rect-9").is_some());
    assert!(doc.get("sticker-1").is_none());
}
